<section class="app-panel dashboard-card tool-card security-focus-card" id="password">
  <div class="security-panel-heading"><div><span><?=store_h(store_t('Password'))?></span><h2><?=store_h(store_t('Change your password'))?></h2><p><?=store_h(store_t('Changing your password closes all website sessions, including this browser. You will sign in again with the new password.'))?></p></div><div class="security-impact"><strong><?=store_h(store_t('SESSION RESET'))?></strong><span><?=store_h(store_t('Every signed-in browser will be closed.'))?></span></div></div>
  <form method="post" class="security-form password-form security-password-form"><?=csrf_field()?><input type="hidden" name="action" value="change_password"><label><span><?=store_h(store_t('Current password'))?></span><input type="password" name="current_password" required maxlength="256" autocomplete="current-password"></label><label><span><?=store_h(store_t('New password'))?></span><input type="password" name="new_password" required minlength="8" maxlength="256" autocomplete="new-password"></label><label><span><?=store_h(store_t('Confirm new password'))?></span><input type="password" name="confirm_password" required minlength="8" maxlength="256" autocomplete="new-password"></label><button class="app-button tool-button primary" type="submit"><?=store_h(store_t('Change password'))?> <span aria-hidden="true">→</span></button></form>
</section>

<details class="account-settings-advanced" id="advanced-security"><summary><?=store_h(store_t('Advanced security: signed-in browsers & activity'))?></summary>
<section class="security-summary" aria-label="<?=store_h(store_t('Security summary'))?>">
  <div><span><?=store_h(store_t('Active browser sessions'))?></span><strong><?=$activeBrowserSessions?></strong></div>
  <div><span><?=store_h(store_t('Two-factor protection'))?></span><strong><?=store_h(store_t(!empty($user['totp_enabled'])?'ENABLED':'ACCOUNT READY'))?></strong></div>
  <div><span><?=store_h(store_t('Last successful sign-in'))?></span><strong><?=$lastSuccessfulLogin?web_local_datetime($lastSuccessfulLogin['created_at']??null,store_t('RECENT')):store_h(store_t('NO HISTORY'))?></strong></div>
</section>

<nav class="security-section-nav" aria-label="<?=store_h(store_t('Security sections'))?>"><a href="#password"><?=store_h(store_t('Password'))?></a><a href="#web-sessions"><?=store_h(store_t('Browser sessions'))?></a><a href="#login-history"><?=store_h(store_t('Login history'))?></a></nav>

<section class="app-panel dashboard-card tool-card security-focus-card" id="web-sessions">
  <div class="security-panel-heading"><div><span><?=store_h(store_t('Browser sessions'))?></span><h2><?=store_h(store_t('Your signed-in browsers'))?></h2><p><?=store_h(store_t('Review active website sessions and close anything you do not recognize.'))?></p></div>
  <?php $otherActive=0;foreach($webSessions as $ws){if(empty($ws['revoked_at'])&&!hash_equals((string)$ws['session_hash'],$currentWebSessionHash))$otherActive++;}?>
  <?php if($otherActive>0):?><form method="post" data-confirm="<?=store_h(store_t('Log out every other website session?'))?>" data-confirm-tone="warning"><?=csrf_field()?><input type="hidden" name="action" value="logout_other_web_sessions"><button class="app-button tool-button warning" type="submit"><?=store_h(store_t('Log out other sessions'))?></button></form><?php endif;?></div>
  <?php if(!$sessionSchemaReady):?><p class="tool-empty"><?=store_h(store_t('Session controls are temporarily unavailable while security services are being prepared.'))?></p>
  <?php elseif(!$webSessions):?><p class="tool-empty"><?=store_h(store_t('No browser sessions recorded yet.'))?></p>
  <?php else:?><div class="web-session-list"><?php foreach($webSessions as $ws):$isCurrent=$currentWebSessionHash!==''&&hash_equals((string)$ws['session_hash'],$currentWebSessionHash);$isActive=empty($ws['revoked_at']);?><article class="web-session-row <?=$isCurrent?'is-current':''?> <?=$isActive?'':'is-revoked'?>"><div><div class="web-session-title"><strong><?=htmlspecialchars(web_user_agent_label($ws['user_agent']??''),ENT_QUOTES,'UTF-8')?></strong><?php if($isCurrent):?><span class="app-badge account-status-badge is-on"><?=store_h(store_t('CURRENT'))?></span><?php elseif($isActive):?><span class="app-badge account-status-badge is-neutral"><?=store_h(store_t('ACTIVE'))?></span><?php else:?><span class="app-badge account-status-badge is-off"><?=store_h(store_t('CLOSED'))?></span><?php endif;?></div><small><?=htmlspecialchars((string)($ws['ip_address']??store_t('Unknown IP')),ENT_QUOTES,'UTF-8')?> · <?=store_h(store_t('Last active'))?> <?=web_local_datetime($ws['last_seen_at']??null,store_t('Unknown'))?></small></div><?php if($isActive&&!$isCurrent):?><form method="post" data-confirm="<?=store_h(store_t('Log out this browser session?'))?>" data-confirm-tone="warning"><?=csrf_field()?><input type="hidden" name="action" value="logout_web_session"><input type="hidden" name="session_id" value="<?=(int)$ws['id']?>"><button class="app-button tool-button warning" type="submit"><?=store_h(store_t('Log out'))?></button></form><?php endif;?></article><?php endforeach;?></div><?php endif;?>
</section>

<section class="app-panel dashboard-card tool-card security-focus-card" id="login-history">
  <div class="security-panel-heading"><div><span><?=store_h(store_t('Login history'))?></span><h2><?=store_h(store_t('Recent sign-in attempts'))?></h2><p><?=store_h(store_t('Password, two-factor, registration and password-reset events associated with your account.'))?></p></div></div>
  <?php if(!$loginHistory):?><p class="tool-empty"><?=store_h(store_t('No login history recorded yet.'))?></p><?php else:?><div class="security-history-list"><?php foreach($loginHistory as $entry):?><div class="security-history-row"><div><strong><?=store_h(store_t(!empty($entry['success'])?'SUCCESS':'FAILED'))?> · <?=htmlspecialchars(strtoupper((string)$entry['auth_stage']),ENT_QUOTES,'UTF-8')?></strong><small><?=htmlspecialchars(web_user_agent_label($entry['user_agent']??''),ENT_QUOTES,'UTF-8')?> · <?=htmlspecialchars((string)($entry['ip_address']??store_t('Unknown IP')),ENT_QUOTES,'UTF-8')?></small></div><?=web_local_datetime($entry['created_at']??null,store_t('Unknown'))?></div><?php endforeach;?></div><?php endif;?>
</section>
</details>
<?php account_page_end('ACCOUNT SETTINGS'); ?>
